package com.neuroassist.gest.infrastructure.security;

import org.hibernate.context.spi.CurrentTenantIdentifierResolver;
import org.springframework.stereotype.Component;

/**
 * Tells Hibernate which tenant identifier to use for the current Session. Pairs with {@link
 * MultiTenantConnectionProvider} to realise schema-per-tenant (multi-tenancy.arch.json, D-063).
 * Generated by D-071. Updated in P3: resolves the raw tenantId from {@link TenantContextHolder} and
 * prefixes it with {@code t_} to form the actual schema name (e.g., "emp_test" → "t_emp_test"). The
 * resolved schema name is then passed to {@link MultiTenantConnectionProvider#getConnection} which
 * uses it directly in {@code SET search_path}.
 */
@Component
public class TenantIdentifierResolver implements CurrentTenantIdentifierResolver<String> {

    private static final String GLOBAL_FALLBACK = "neuroassist_global";
    private static final String SCHEMA_PREFIX = "t_";

    @Override
    public String resolveCurrentTenantIdentifier() {
        String tenant = TenantContextHolder.getTenantIdOrNull();
        if (tenant == null || tenant.isBlank()) {
            return GLOBAL_FALLBACK;
        }
        // Return the tenant identifier as-is. Mapping it to a schema name is
        // MultiTenantConnectionProvider's job — it resolves schema_nome from the tenant catalogue
        // and only then falls back to the t_<tenant> convention. Prefixing here hid the real
        // identifier from that lookup and forced every ACS-issued tenant onto a schema that does
        // not exist (E2E-009 / C-15).
        return tenant;
    }

    @Override
    public boolean validateExistingCurrentSessions() {
        // Re-validate the tenant identifier on every Session reuse so a
        // stale ThreadLocal can't leak across pooled threads.
        return true;
    }
}
